243→// handleSessionStartCommon is the shared implementation for session start hooks.
244→// Used by both Claude Code and Gemini CLI handlers.
245→func handleSessionStartCommon() error {
246→	ag, err := GetCurrentHookAgent()
247→	if err != nil {
248→		return fmt.Errorf("failed to get agent: %w", err)
249→	}
250→
251→	input, err := ag.ParseHookInput(agent.HookSessionStart, os.Stdin)
252→	if err != nil {
253→		return fmt.Errorf("failed to parse hook input: %w", err)
254→	}
255→
256→	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "hooks"), ag.Name())
257→	logging.Info(logCtx, "session-start",
258→		slog.String("hook", "session-start"),
259→		slog.String("hook_type", "agent"),
260→		slog.String("model_session_id", input.SessionID),
261→		slog.String("transcript_path", input.SessionRef),
262→	)
263→
264→	if input.SessionID == "" {
265→		return errors.New("no session_id in input")
266→	}
267→
268→	// Build informational message
269→	message := "\n\nPowered by Entire:\n  This conversation will be linked to your next commit."
270→
271→	// Append wingman note if enabled, with pending review indication
272→	if settings.IsWingmanEnabled() {
273→		if repoRoot, rootErr := paths.RepoRoot(); rootErr == nil {
274→			if _, statErr := os.Stat(filepath.Join(repoRoot, wingmanReviewFile)); statErr == nil {
275→				message += "\n  Wingman: a review is pending and will be addressed on your next prompt."
276→			} else {
277→				message += "\n  Wingman is active: your changes will be automatically reviewed."
278→			}
279→		} else {
280→			message += "\n  Wingman is active: your changes will be automatically reviewed."
281→		}
282→	}
283→
284→	// Check for concurrent sessions and append count if any
285→	strat := GetStrategy()
286→	if concurrentChecker, ok := strat.(strategy.ConcurrentSessionChecker); ok {
287→		if count, err := concurrentChecker.CountOtherActiveSessionsWithCheckpoints(input.SessionID); err == nil && count > 0 {
288→			message += fmt.Sprintf("\n  %d other active conversation(s) in this workspace will also be included.\n  Use 'entire status' for more information.", count)
289→		}
290→	}
291→
292→	// Output informational message using agent-specific format
293→	if err := outputHookResponse(message); err != nil {
294→		return err
295→	}
296→
297→	// Fire EventSessionStart for the current session (if state exists).
298→	// This handles ENDED → IDLE (re-entering a session).
299→	// TODO(ENT-221): dispatch ActionWarnStaleSession for ACTIVE/ACTIVE_COMMITTED sessions.
300→	if state, loadErr := strategy.LoadSessionState(input.SessionID); loadErr != nil {
301→		fmt.Fprintf(os.Stderr, "Warning: failed to load session state on start: %v\n", loadErr)
302→	} else if state != nil {
303→		strategy.TransitionAndLog(state, session.EventSessionStart, session.TransitionContext{})
304→		if saveErr := strategy.SaveSessionState(state); saveErr != nil {
305→			fmt.Fprintf(os.Stderr, "Warning: failed to update session state on start: %v\n", saveErr)
306→		}
307→	}
308→
309→	return nil
310→}
