312→// hookSpecificOutput contains event-specific fields nested under hookSpecificOutput
313→// in the hook response JSON. Claude Code requires this nesting for additionalContext
314→// to be injected into the agent's conversation.
315→type hookSpecificOutput struct {
316→	HookEventName     string `json:"hookEventName"`
317→	AdditionalContext string `json:"additionalContext,omitempty"`
