320→// hookResponse represents a JSON response to a Claude Code hook.
321→// systemMessage is shown to the user as a warning/info message.
322→// hookSpecificOutput contains event-specific fields like additionalContext.
323→type hookResponse struct {
324→	SystemMessage      string              `json:"systemMessage,omitempty"`
325→	HookSpecificOutput *hookSpecificOutput `json:"hookSpecificOutput,omitempty"`
326→}
