328→// outputHookResponse outputs a JSON response with additionalContext for
329→// SessionStart hooks. The context is injected into the agent's conversation.
330→func outputHookResponse(context string) error {
331→	resp := hookResponse{
332→		SystemMessage: context,
333→		HookSpecificOutput: &hookSpecificOutput{
334→			HookEventName:     "SessionStart",
335→			AdditionalContext: context,
336→		},
337→	}
338→	if err := json.NewEncoder(os.Stdout).Encode(resp); err != nil {
339→		return fmt.Errorf("failed to encode hook response: %w", err)
340→	}
341→	return nil
342→}
